import json, random, datetime
from typing import Any, Dict

EMPTY_MARKS = ('', '待补充', '系统待生成', '无', '暂无')
FUSION_PRODUCT_TYPES = ('家庭基础套餐', '融合套餐')
BASE_FIELDS = (
    ('name', '销售品名称'), ('quantity', '销售品数量'), ('product_type', '产品类型'), ('series', '所属系列'),
    ('price', '套餐档位（月费）'), ('resources', '套内资源'), ('out_price', '套外资费'),
    ('billing_cycle', '计费周期'), ('effective_way', '生效方式'), ('validity', '套餐有效期'),
    ('change_rule', '变更规则'), ('cancel_rule', '退订/拆机规则'),
)
FUSION_EXTRA_FIELDS = (('members', '融合成员'),)
PRICE_FIELDS = ('price',)
REQUIRED_FIELDS = ('price', 'resources')

def _norm(v):
    if v is None:
        return ''
    if isinstance(v, bool):
        return '是' if v else '否'
    if isinstance(v, (int, float)):
        return v
    s = str(v).strip()
    return '' if s in EMPTY_MARKS else s

def _gen_req_id():
    ts = datetime.datetime.now().strftime('%Y%m%d%H%M%S')
    return 'PLAN%s%03d' % (ts, random.randint(0, 999))

def _norm_qty(v):
    # 销售品数量归一：缺省/非法 → 1，正数取整
    if v is None:
        return 1
    s = str(v).strip()
    if s == '':
        return 1
    import re
    m = re.search(r'\d+', s)
    if not m:
        return 1
    n = int(m.group())
    return n if n > 0 else 1

def _loose_obj(s):
    t = s.strip()
    if t[:3] == '```':
        t = t[3:]
        if t[:4].lower() == 'json':
            t = t[4:]
        if t[-3:] == '```':
            t = t[:-3]
        t = t.strip()
    try:
        return json.loads(t)
    except Exception:
        pass
    starts = [x for x in (t.find('{'), t.find('[')) if x >= 0]
    if not starts:
        return None
    st = min(starts)
    op = t[st]
    cl = '}' if op == '{' else ']'
    d = 0
    for i in range(st, len(t)):
        c = t[i]
        if c == op:
            d += 1
        elif c == cl:
            d -= 1
            if d == 0:
                try:
                    return json.loads(t[st:i + 1])
                except Exception:
                    return None
    return None

def _unwrap(o):
    for _ in range(5):
        if not isinstance(o, dict):
            return o
        nx = None
        for k in ('offers', 'offers_json', 'elements', 'elements_json', 'data', 'result'):
            if k in o:
                nx = o[k]
                break
        if nx is None:
            return o
        if isinstance(nx, str):
            n2 = _loose_obj(nx)
            if n2 is None:
                return o
            o = n2
        else:
            o = nx
    return o

def _parse(raw):
    if isinstance(raw, dict):
        return raw
    if isinstance(raw, list):
        return {'offers': raw}
    if not isinstance(raw, str) or not raw.strip():
        return {}
    o = _unwrap(_loose_obj(raw))
    if isinstance(o, list):
        return {'offers': o}
    if isinstance(o, dict):
        if isinstance(o.get('offers'), list):
            return o
        return {'offers': [o]}
    return {}

def fields_for(product_type):
    pt = _norm(product_type)
    # 融合判定：枚举命中 或 产品类型文本含“融合”二字（兼容 LLM 输出“融合套餐/5G-A融合”等变体）
    if pt in FUSION_PRODUCT_TYPES or '融合' in str(pt):
        return BASE_FIELDS + FUSION_EXTRA_FIELDS
    return BASE_FIELDS

async def main(args):
    p = args.params
    # V3.12 多商品：入参 offers_json（N 品字段数组），兼容旧 elements_json（单品平面 JSON → 包装为 1 品）
    raw = p.get('offers_json') or p.get('elements_json') or ''
    obj = _parse(raw)
    if isinstance(obj, dict) and isinstance(obj.get('offers'), list):
        elements_list = obj.get('offers')
    elif isinstance(obj, dict) and obj:
        elements_list = [obj]
    else:
        elements_list = []
    req_id = str(p.get('req_id') or _gen_req_id())
    reporter = str(p.get('reporter') or '')
    need_summary = str(p.get('need_summary') or '')
    today = datetime.date.today().strftime('%Y-%m-%d')
    def cell(v):
        return '待补充' if v == '' else str(v)
    def table(rows):
        if not rows:
            return []
        out = ['| 字段 | 内容 |', '| --- | --- |']
        out += ['| %s | %s |' % (k, v) for k, v in rows]
        return out
    offers_flat = []
    pending_all = []
    lines = []
    lines.append('## 销售品需求提报单')
    base_rows = [('需求单号', req_id), ('提报日期', today), ('商品数量', str(len(elements_list)))]
    if reporter:
        base_rows.append(('提报人', reporter))
    if need_summary:
        base_rows.append(('需求概述', need_summary))
    lines.append('### 1. 需求基本信息')
    lines += table(base_rows)
    lines.append('')
    for idx, elements in enumerate(elements_list, start=1):
        if not isinstance(elements, dict):
            continue
        offer_seq = int(elements.get('offer_seq') or idx)
        quantity = _norm_qty(elements.get('quantity'))
        fmt = lambda k: _norm(elements.get(k))
        fields = fields_for(elements.get('product_type'))
        values = {}
        pending = []
        for key, label in fields:
            if key == 'quantity':
                values[key] = quantity
                continue
            val = fmt(key)
            values[key] = val
            if key in REQUIRED_FIELDS and (val == '' or (key in PRICE_FIELDS and val in (0, '0', '0元'))):
                pending.append(label)
        flat = {'offer_seq': offer_seq}
        flat.update(values)
        offers_flat.append(flat)
        if pending:
            pending_all.append('第%d档（%s）：%s' % (offer_seq, cell(values.get('name')), '、'.join(pending)))
        prod_rows = [('销售品名称', cell(values['name'])), ('销售品数量', str(quantity)), ('产品类型', cell(values['product_type']))]
        if values['series']:
            prod_rows.append(('所属系列', values['series']))
        if values.get('members'):
            prod_rows.append(('融合成员', values['members']))
        fee_rows = [('套餐档位（月费）', (str(values['price']) + ' 元/月') if values['price'] != '' else '待补充')]
        if values['resources']:
            fee_rows.append(('套内资源', values['resources']))
        if values['out_price']:
            fee_rows.append(('套外资费', values['out_price']))
        if values['billing_cycle']:
            fee_rows.append(('计费周期', values['billing_cycle']))
        order_rows = []
        if values['effective_way']:
            order_rows.append(('生效方式', values['effective_way']))
        if values['validity']:
            order_rows.append(('套餐有效期', values['validity']))
        if values['change_rule']:
            order_rows.append(('变更规则', values['change_rule']))
        if values['cancel_rule']:
            order_rows.append(('退订/拆机规则', values['cancel_rule']))
        lines.append('### 商品 %d（offer_seq=%d）：%s' % (idx, offer_seq, cell(values['name'])))
        lines.append('#### 产品/销售品信息')
        lines += table(prod_rows)
        lines.append('')
        lines.append('#### 资费方案要点')
        lines += table(fee_rows)
        lines.append('')
        lines.append('#### 订购/变更/退订规则')
        if order_rows:
            lines += table(order_rows)
        else:
            lines.append('（未提及，从宽不催补）')
        lines.append('')
    lines.append('### 待补充字段')
    lines.append('\n'.join(pending_all) if pending_all else '无')
    while lines and lines[-1] == '':
        lines.pop()
    text = '\n'.join(lines)
    offers_list_lines = ['| 序号 | 销售品名称 | 数量 |', '| --- | --- | --- |']
    offers_list_lines += ['| %d | %s | %d |' % (o.get('offer_seq', i), cell(o.get('name')), o.get('quantity', 1)) for i, o in enumerate(offers_flat, start=1)]
    offers_list = '\n'.join(offers_list_lines) if offers_flat else '无'
    ret: Output = {
        "report_text": text,
        "pending_fields": '；'.join(pending_all),
        "pending_count": (str(len(pending_all)) if pending_all else ''),
        "req_id": req_id,
        "offers": json.dumps({'req_id': req_id, 'offer_count': len(offers_flat), 'offers': offers_flat}, ensure_ascii=False),
        "offers_list": offers_list,
    }
    return ret

from typing import Any, Dict

def _csv(v):
    # offers 入参可能是 JSON 数组字符串或已归一数组，拍平为 offer_id 逗号串
    import json as _json
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return ''
        try:
            v = _json.loads(s)
        except Exception:
            v = s
    if isinstance(v, dict) and isinstance(v.get('offers'), list):
        v = v['offers']
    if not isinstance(v, list):
        return ''
    ids = []
    for o in v:
        oid = str((o or {}).get('offer_id') or '') if isinstance(o, dict) else ''
        if oid:
            ids.append(oid)
    return ','.join(ids)

async def main(args):
    p = args.params
    chat_id = str(p.get('chat_id') or '')
    offer_id = str(p.get('offer_id') or '')
    offer_name = str(p.get('offer_name') or '')
    req_id = str(p.get('req_id') or '')
    offers_csv = _csv(p.get('offers'))
    qs = ('?chatId=' + chat_id + '&req_id=' + req_id + '&stage=00&view=stage')
    if offer_id:
        qs = ('?offer_id=' + offer_id + '&name=' + offer_name + '&chatId=' + chat_id + '&req_id=' + req_id + '&stage=00&view=stage')
    if offers_csv:
        qs += '&offers=' + offers_csv
    biz_url = 'http://szyg-stq-test.anhuitelecom.com:10001/prod-ai/ops-web/config-workbench.html' + qs
    panel = (
        "\n\n```xsbot-panel\n"
        + '{"version":"1.0","message_id":"' + chat_id + '",'
        + '"panels":[{"panel":"right","mode":"external","url":"' + biz_url + '","title":"需求提报单"}]}'
        + "\n```\n"
    )
    result: Output = {'panel': panel}
    return result

