def _load(text):
    if isinstance(text, list):
        return {'offers': text}
    if isinstance(text, dict):
        return text
    if not isinstance(text, str) or not text.strip():
        return {}
    try:
        obj = json.loads(text)
        if isinstance(obj, list):
            return {'offers': obj}
        return obj if isinstance(obj, dict) else {}
    except Exception:
        try:
            t = text.strip()
            if ':' in t and not t.startswith('{') and not t.startswith('['):
                t = t.split(':', 1)[1].strip()
            obj = json.loads(t)
            if isinstance(obj, list):
                return {'offers': obj}
            return obj if isinstance(obj, dict) else {}
        except Exception:
            return {}

