                'offers', 'req_id', 'plan_json')

def _any(v):
    # 平台出参可能是已序列化 JSON 字符串，也可能是原始 list/str；统一尝试解析
    if isinstance(v, (list, dict)):
        return v
    if v is None:
        return None
    s = str(v)
    if not s.strip():
        return None
    t = s.strip()
    if t[0] in '[{' and t[-1] in ']}':
        try:
            return json.loads(t)
        except Exception:
            return s
    return s

