import json
import asyncio
import urllib.request
from typing import Any, Dict

SQL_URL = 'http://172.30.8.52:6174/api/v1/appstore/audit/sql-query'
INTERVAL = 5
MAX_RETRY = 60
MAX_CONSECUTIVE_FAIL = 5
SQL_ID_FINISH = '20260626001'

def _load(v):
    if isinstance(v, list):
        return v
    if isinstance(v, dict):
        return [v]
    if not isinstance(v, str) or not v.strip():
        return []
    try:
        obj = json.loads(v)
        if isinstance(obj, dict) and isinstance(obj.get('offers'), list):
            return obj['offers']
        return obj if isinstance(obj, list) else ([obj] if isinstance(obj, dict) else [])
    except Exception:
        return []

def _first_sql_row(resp):
    # B4 返回 {resultCode, execute_sql_resp:[{...}]}；完成标志/结论在首行内，需解包
    if not isinstance(resp, dict):
        return {}
    rows = resp.get('execute_sql_resp') or resp.get('executeSqlResp') or []
    if isinstance(rows, list) and rows and isinstance(rows[0], dict):
        return rows[0]
    if isinstance(rows, dict):
        return rows
    return resp

def _is_finished(request_ids):
    # 单品完成判定：查询其 requestIds，返回 (ok, finished)
    if not request_ids:
        return True, True
    try:
        body = json.dumps({'sqlId': SQL_ID_FINISH,
                           'params': 'requestIds:' + request_ids}).encode('utf-8')
        req = urllib.request.Request(SQL_URL, data=body,
                                     headers={'Content-Type': 'application/json'})
        with urllib.request.urlopen(req, timeout=30) as http_resp:
            resp = json.loads(http_resp.read().decode('utf-8'))
    except Exception:
        return False, False
    if not isinstance(resp, dict):
        return False, False
    row = _first_sql_row(resp)
    finished = str(row.get('isAllFinished', row.get('finished', ''))).lower()
    return True, finished in ('y', 'yes', 'true', '1')

async def main(args):
    p = args.params
    offers = [o for o in _load(p.get('offers')) if isinstance(o, dict)]
    if not offers:
        # 兼容：顶层直接给逗号拼接的 requestIds
        rid = str(p.get('requestIds') or '')
        if rid:
            offers = [{'offer_seq': 1, 'offer_id': '', 'requestIds': rid}]
    if not offers:
        ret: Output = {'completed': 'false',
                       'fail_reason': '缺少 requestIds，请先发起稽核（环节4a）', 'offers': '[]'}
        return ret
    norm = []
    for i, o in enumerate(offers, start=1):
        seq = o.get('offer_seq') if o.get('offer_seq') not in (None, '') else i
        rid = o.get('requestIds') or o.get('request_ids') or o.get('request_id') or ''
        if isinstance(rid, list):
            rid = ','.join(str(x) for x in rid if str(x))
        norm.append({'offer_seq': seq,
                     'offer_id': str(o.get('offer_id') or o.get('offerId') or ''),
                     'requestIds': str(rid or '')})
    consecutive_fail = 0
    for i in range(MAX_RETRY):
        all_done = True
        round_ok = True
        for o in norm:
            ok, finished = _is_finished(o['requestIds'])
            if not ok:
                round_ok = False
                break
            if not finished:
                all_done = False
                break
        if not round_ok:
            consecutive_fail += 1
            if consecutive_fail >= MAX_CONSECUTIVE_FAIL:
                ret: Output = {'completed': 'false',
                               'fail_reason': '连续查询失败5次，转人工',
                               'offers': json.dumps(norm, ensure_ascii=False)}
                return ret
            await asyncio.sleep(INTERVAL)
            continue
        consecutive_fail = 0
        if all_done:
            ret: Output = {'completed': 'true', 'fail_reason': '',
                           'offers': json.dumps(norm, ensure_ascii=False)}
            return ret
        await asyncio.sleep(INTERVAL)
    ret: Output = {'completed': 'false',
                   'fail_reason': '稽核处理中，请稍后回复【查询稽核结果】续查',
                   'offers': json.dumps(norm, ensure_ascii=False)}
    return ret

